import type { ReactNode } from 'react';
import type { FileManagerFileStat, FileManagerFileSystem, FileManagerProps } from '../file-manager';

export type FilePickerAcceptType = {
	accept: Record<string, readonly string[]>;
	description?: string;
};

export type DirectoryPickerResult = {
	kind: 'directory';
	path: string;
};

export type SaveFilePickerResult = {
	directory: string;
	existing?: FileManagerFileStat;
	kind: 'file';
	name: string;
	path: string;
};

export type FilePickerMessages = {
	cancel: string;
	confirmDirectory: string;
	confirmOpen: string;
	confirmSave: string;
	emptyDirectory: string;
	emptyFiles: string;
	fileName: string;
	fileType: string;
	noFile: string;
	openingDirectory: string;
	overwrite: string;
	overwriteDescription: (name: string) => ReactNode;
	overwriteTitle: string;
	savingTarget: string;
};

export type FilePickerCommonProps = Omit<
	FileManagerProps,
	| 'capabilities'
	| 'emptyState'
	| 'filterEntry'
	| 'footer'
	| 'onActivateEntry'
	| 'onOpenFile'
	| 'readOnly'
	| 'selectionMode'
	| 'store'
	| 'title'
> & {
	allowCreateDirectory?: boolean;
	fileSystem: FileManagerFileSystem;
	messages?: Partial<FilePickerMessages>;
	onCancel?: () => void;
	preview?: boolean;
	title?: ReactNode;
};

export type SingleFilePickerProps = FilePickerCommonProps & {
	accept?: readonly FilePickerAcceptType[];
	multiple?: false;
	onConfirm: (result: FileManagerFileStat) => void;
};

export type MultipleFilePickerProps = FilePickerCommonProps & {
	accept?: readonly FilePickerAcceptType[];
	multiple: true;
	onConfirm: (result: FileManagerFileStat[]) => void;
};

export type FilePickerProps = MultipleFilePickerProps | SingleFilePickerProps;

export type DirectoryPickerProps = FilePickerCommonProps & {
	onConfirm: (result: DirectoryPickerResult) => void;
};

export type SaveFilePickerProps = FilePickerCommonProps & {
	accept?: readonly FilePickerAcceptType[];
	onConfirm: (result: SaveFilePickerResult) => void;
	suggestedName?: string;
};

export type FilePickerMode = 'directory' | 'open' | 'save';

export type FilePickerCoreProps = FilePickerCommonProps & {
	accept?: readonly FilePickerAcceptType[];
	mode: FilePickerMode;
	multiple?: boolean;
	onConfirm: (
		result: DirectoryPickerResult | FileManagerFileStat | FileManagerFileStat[] | SaveFilePickerResult,
	) => void;
	suggestedName?: string;
};

import type { FileManagerFileStat } from '../file-manager';
import { joinFileManagerPath, validateFileManagerName } from '../file-manager';
import type { FilePickerAcceptType, SaveFilePickerResult } from './file-picker-types';

export function matchesFilePickerAccept(entry: FileManagerFileStat, accept?: readonly FilePickerAcceptType[]): boolean {
	if (entry.kind === 'directory' || !accept?.length) return true;
	const extension = getExtension(entry.name);
	const mime = getEntryMime(entry);
	return accept.some((group) =>
		Object.entries(group.accept).some(([pattern, extensions]) => {
			if (pattern.trim() === '*/*' || extensions.some((candidate) => candidate.trim() === '*')) return true;
			if (extensions.some((candidate) => normalizeExtension(candidate) === extension)) return true;
			return mime ? matchesMime(mime, pattern) : false;
		}),
	);
}

export function filterFilePickerEntries(
	entries: readonly FileManagerFileStat[],
	options: { accept?: readonly FilePickerAcceptType[]; directoriesOnly?: boolean },
): FileManagerFileStat[] {
	return entries.filter((entry) =>
		options.directoriesOnly
			? entry.kind === 'directory'
			: entry.kind === 'directory' || matchesFilePickerAccept(entry, options.accept),
	);
}

export function getSelectedFilePickerEntries(
	entries: readonly FileManagerFileStat[],
	selectedPaths: readonly string[],
	kind: 'directory' | 'file',
): FileManagerFileStat[] {
	const selected = new Set(selectedPaths);
	return entries.filter((entry) => entry.kind === kind && selected.has(entry.path));
}

export function createSaveFilePickerTarget(
	directory: string,
	name: string,
	existing?: FileManagerFileStat,
): { error?: string; result?: SaveFilePickerResult } {
	const error = validateFileManagerName(name);
	if (error) return { error };
	const normalizedName = name.trim();
	if (existing?.kind === 'directory') return { error: '不能覆盖同名目录' };
	return {
		result: {
			directory,
			existing,
			kind: 'file',
			name: normalizedName,
			path: joinFileManagerPath(directory, normalizedName),
		},
	};
}

function getExtension(name: string): string {
	const dot = name.lastIndexOf('.');
	return dot > 0 ? name.slice(dot).toLowerCase() : '';
}

function normalizeExtension(value: string): string {
	const normalized = value.trim().toLowerCase();
	if (!normalized || normalized === '*') return normalized;
	return normalized.startsWith('.') ? normalized : `.${normalized}`;
}

function getEntryMime(entry: FileManagerFileStat): string | undefined {
	for (const key of ['type', 'mimeType', 'mime']) {
		const value = entry.meta[key];
		if (typeof value === 'string' && value.includes('/')) return value.toLowerCase();
	}
	return undefined;
}

function matchesMime(mime: string, pattern: string): boolean {
	const normalized = pattern.trim().toLowerCase();
	if (normalized === '*/*') return true;
	if (normalized.endsWith('/*')) return mime.startsWith(normalized.slice(0, -1));
	return mime === normalized;
}

import Emittery from 'emittery';
import { createStore } from 'zustand/vanilla';
import { mutative } from 'zustand-mutative';
import type { SaveFilePickerResult } from './file-picker-types';

export const FilePickerEventType = {
	Cancel: 'FilePicker:Cancel',
	Confirm: 'FilePicker:Confirm',
	ConfirmOverwrite: 'FilePicker:ConfirmOverwrite',
} as const;

export type FilePickerEventData = {
	[FilePickerEventType.Cancel]: Record<string, never>;
	[FilePickerEventType.Confirm]: Record<string, never>;
	[FilePickerEventType.ConfirmOverwrite]: Record<string, never>;
};

export type FilePickerStoreState = {
	events: Emittery<FilePickerEventData>;
	filter: { acceptIndex: number };
	input: { name: string };
	navigation: { pending: boolean };
	overwrite: { target?: SaveFilePickerResult };
	request: { error?: string; id: number; status: 'idle' | 'checking' };
	actions: {
		beginRequest: () => number;
		beginNavigation: () => void;
		cancel: () => void;
		clearOverwrite: () => void;
		confirm: () => void;
		confirmOverwrite: () => void;
		failRequest: (id: number, error: string) => void;
		finishRequest: (id: number) => void;
		finishNavigation: () => void;
		invalidate: () => void;
		setAcceptIndex: (index: number) => void;
		setName: (name: string) => void;
		showOverwrite: (id: number, target: SaveFilePickerResult) => void;
	};
};

export type FilePickerStore = ReturnType<typeof createFilePickerStore>;

export function createFilePickerStore(options: { suggestedName?: string } = {}) {
	const events = new Emittery<FilePickerEventData>();
	return createStore(
		mutative<FilePickerStoreState>((setState) => ({
			events,
			filter: { acceptIndex: 0 },
			input: { name: options.suggestedName ?? '' },
			navigation: { pending: false },
			overwrite: {},
			request: { id: 0, status: 'idle' },
			actions: {
				beginNavigation: () =>
					setState((state) => {
						state.navigation.pending = true;
						state.request.id += 1;
						state.request.status = 'idle';
						state.request.error = undefined;
						state.overwrite.target = undefined;
					}),
				beginRequest: () => {
					let id = 0;
					setState((state) => {
						state.request.id += 1;
						id = state.request.id;
						state.request.status = 'checking';
						state.request.error = undefined;
						state.overwrite.target = undefined;
					});
					return id;
				},
				cancel: () => void events.emit(FilePickerEventType.Cancel, {}),
				clearOverwrite: () => setState((state) => void (state.overwrite.target = undefined)),
				confirm: () => void events.emit(FilePickerEventType.Confirm, {}),
				confirmOverwrite: () => void events.emit(FilePickerEventType.ConfirmOverwrite, {}),
				failRequest: (id, error) =>
					setState((state) => {
						if (state.request.id !== id) return;
						state.request.status = 'idle';
						state.request.error = error;
					}),
				finishRequest: (id) =>
					setState((state) => {
						if (state.request.id !== id) return;
						state.request.status = 'idle';
						state.request.error = undefined;
					}),
				finishNavigation: () => setState((state) => void (state.navigation.pending = false)),
				invalidate: () =>
					setState((state) => {
						state.request.id += 1;
						state.request.status = 'idle';
						state.request.error = undefined;
						state.overwrite.target = undefined;
						state.navigation.pending = false;
					}),
				setAcceptIndex: (index) =>
					setState((state) => {
						state.filter.acceptIndex = Math.max(0, Math.floor(index));
						state.request.id += 1;
						state.request.status = 'idle';
						state.request.error = undefined;
						state.overwrite.target = undefined;
					}),
				setName: (name) =>
					setState((state) => {
						state.input.name = name;
						state.request.id += 1;
						state.request.status = 'idle';
						state.request.error = undefined;
						state.overwrite.target = undefined;
					}),
				showOverwrite: (id, target) =>
					setState((state) => {
						if (state.request.id !== id) return;
						state.request.status = 'idle';
						state.overwrite.target = target;
					}),
			},
		})),
	);
}

'use client';

import { createContext, type PropsWithChildren, useContext, useState } from 'react';
import { useStore } from 'zustand';
import { createFilePickerStore, type FilePickerStore, type FilePickerStoreState } from './file-picker-store';

const FilePickerContext = createContext<FilePickerStore | null>(null);

export function FilePickerProvider({
	children,
	store,
	suggestedName,
}: PropsWithChildren<{ store?: FilePickerStore; suggestedName?: string }>) {
	const [localStore] = useState(() => store ?? createFilePickerStore({ suggestedName }));
	return <FilePickerContext.Provider value={store ?? localStore}>{children}</FilePickerContext.Provider>;
}

export function useFilePickerStoreContext(): FilePickerStore {
	const store = useContext(FilePickerContext);
	if (!store) throw new Error('useFilePickerStore must be used within FilePickerProvider');
	return store;
}

export function useFilePickerStore<T>(selector: (state: FilePickerStoreState) => T): T {
	return useStore(useFilePickerStoreContext(), selector);
}

export function useFilePickerActions() {
	return useFilePickerStore((state) => state.actions);
}

'use client';

import { useEffect, useRef } from 'react';
import {
	type FileManagerFileStat,
	type FileManagerFileSystem,
	type FileManagerStore,
	sanitizeFileManagerStat,
} from '../file-manager';
import { createSaveFilePickerTarget, getSelectedFilePickerEntries, matchesFilePickerAccept } from './file-picker-model';
import { FilePickerEventType, type FilePickerStore } from './file-picker-store';
import type {
	DirectoryPickerResult,
	FilePickerAcceptType,
	FilePickerMode,
	SaveFilePickerResult,
} from './file-picker-types';

type FilePickerRuntimeProps = {
	accept?: readonly FilePickerAcceptType[];
	fileManagerStore: FileManagerStore;
	fileSystem: FileManagerFileSystem;
	mode: FilePickerMode;
	messages: { noFile: string };
	multiple: boolean;
	onCancel?: () => void;
	onConfirm: (
		result: DirectoryPickerResult | FileManagerFileStat | FileManagerFileStat[] | SaveFilePickerResult,
	) => void;
	pickerStore: FilePickerStore;
};

export function FilePickerRuntime({
	accept,
	fileManagerStore,
	fileSystem,
	mode,
	messages,
	multiple,
	onCancel,
	onConfirm,
	pickerStore,
}: FilePickerRuntimeProps) {
	const callbacks = useRef({ onCancel, onConfirm });
	callbacks.current = { onCancel, onConfirm };

	useEffect(() => {
		const picker = pickerStore.getState();
		const offCancel = picker.events.on(FilePickerEventType.Cancel, () => {
			pickerStore.getState().actions.invalidate();
			callbacks.current.onCancel?.();
		});
		const offConfirm = picker.events.on(FilePickerEventType.Confirm, () => void confirm());
		const offOverwrite = picker.events.on(FilePickerEventType.ConfirmOverwrite, () => {
			const target = pickerStore.getState().overwrite.target;
			if (!target) return;
			pickerStore.getState().actions.clearOverwrite();
			callbacks.current.onConfirm(target);
		});
		const offFileManager = fileManagerStore.getState().events.on('request', ({ data }) => {
			if (data.type === 'load') pickerStore.getState().actions.beginNavigation();
		});
		const offFileManagerEvent = fileManagerStore.getState().events.on('event', ({ data }) => {
			if (data.type === 'navigated' || (data.type === 'error' && data.action === 'navigate')) {
				pickerStore.getState().actions.finishNavigation();
			}
		});

		async function confirm() {
			const fileManager = fileManagerStore.getState();
			const pickerState = pickerStore.getState();
			if (pickerState.navigation.pending || fileManager.listing.status === 'loading') return;
			const activeAccept = accept?.[pickerState.filter.acceptIndex];
			const acceptedTypes = activeAccept ? [activeAccept] : accept;
			const selectedDirectories = getSelectedFilePickerEntries(
				fileManager.listing.entries,
				fileManager.selection.paths,
				'directory',
			);
			if (mode === 'open') {
				const selected = getSelectedFilePickerEntries(
					fileManager.listing.entries.filter((entry) => matchesFilePickerAccept(entry, acceptedTypes)),
					fileManager.selection.paths,
					'file',
				);
				if (!selected.length) {
					if (selectedDirectories[0]) {
						pickerState.actions.beginNavigation();
						fileManager.actions.requestNavigate(selectedDirectories[0].path);
						return;
					}
					const id = pickerState.actions.beginRequest();
					pickerState.actions.failRequest(id, messages.noFile);
					return;
				}
				callbacks.current.onConfirm(multiple ? selected : selected[0]);
				return;
			}
			if (mode === 'directory') {
				callbacks.current.onConfirm({
					kind: 'directory',
					path: selectedDirectories[0]?.path ?? fileManager.navigation.path,
				});
				return;
			}
			if (selectedDirectories[0]) {
				pickerState.actions.beginNavigation();
				fileManager.actions.requestNavigate(selectedDirectories[0].path);
				return;
			}
			const id = pickerState.actions.beginRequest();
			const target = createSaveFilePickerTarget(fileManager.navigation.path, pickerStore.getState().input.name);
			if (target.error || !target.result) {
				pickerStore.getState().actions.failRequest(id, target.error ?? '文件名无效');
				return;
			}
			try {
				const exists = await fileSystem.exists(target.result.path);
				if (!isCurrent(id)) return;
				if (!exists) {
					pickerStore.getState().actions.finishRequest(id);
					callbacks.current.onConfirm(target.result);
					return;
				}
				const existing = sanitizeFileManagerStat(await fileSystem.stat(target.result.path), target.result.path);
				if (!isCurrent(id)) return;
				const checked = createSaveFilePickerTarget(fileManager.navigation.path, target.result.name, existing);
				if (checked.error || !checked.result) {
					pickerStore.getState().actions.failRequest(id, checked.error ?? '保存目标无效');
					return;
				}
				pickerStore.getState().actions.showOverwrite(id, checked.result);
			} catch (error) {
				if (isCurrent(id)) pickerStore.getState().actions.failRequest(id, getErrorMessage(error));
			}
		}

		function isCurrent(id: number) {
			return pickerStore.getState().request.id === id;
		}

		return () => {
			pickerStore.getState().actions.invalidate();
			offCancel();
			offConfirm();
			offOverwrite();
			offFileManager();
			offFileManagerEvent();
		};
	}, [accept, fileManagerStore, fileSystem, messages, mode, multiple, pickerStore]);
	return null;
}

function getErrorMessage(error: unknown): string {
	return error instanceof Error && error.message ? error.message : '无法检查保存目标';
}

'use client';

import { FolderOpen, Save, X } from 'lucide-react';
import { type FormEvent, type ReactNode, useEffect, useId, useMemo, useRef, useState } from 'react';
import { useStore } from 'zustand';
import { LeftCenterRightLayout } from '@/components/ui/left-center-right-layout';
import { createFileManagerStore, FileManager, type FileManagerStore } from '../file-manager';
import { FilePickerProvider, useFilePickerActions, useFilePickerStore } from './file-picker-context';
import { matchesFilePickerAccept } from './file-picker-model';
import { FilePickerRuntime } from './file-picker-runtime';
import { createFilePickerStore } from './file-picker-store';
import type {
	DirectoryPickerProps,
	FilePickerAcceptType,
	FilePickerCoreProps,
	FilePickerMessages,
	FilePickerProps,
	SaveFilePickerProps,
} from './file-picker-types';

const defaultMessages: FilePickerMessages = {
	cancel: '取消',
	confirmDirectory: '选择文件夹',
	confirmOpen: '打开',
	confirmSave: '保存',
	emptyDirectory: '当前目录没有子目录',
	emptyFiles: '没有符合条件的文件',
	fileName: '文件名',
	fileType: '文件类型',
	noFile: '请选择文件',
	openingDirectory: '正在打开目录…',
	overwrite: '替换',
	overwriteDescription: (name) => `“${name}”已存在。是否替换现有文件？`,
	overwriteTitle: '确认替换文件',
	savingTarget: '正在检查保存目标…',
};

export function FilePicker(props: FilePickerProps) {
	if (props.multiple) {
		const { onConfirm, ...pickerProps } = props;
		return (
			<FilePickerCore
				{...pickerProps}
				mode='open'
				onConfirm={(result) => onConfirm(result as Parameters<typeof onConfirm>[0])}
			/>
		);
	}
	const { onConfirm, ...pickerProps } = props;
	return (
		<FilePickerCore
			{...pickerProps}
			mode='open'
			onConfirm={(result) => onConfirm(result as Parameters<typeof onConfirm>[0])}
		/>
	);
}

export function DirectoryPicker(props: DirectoryPickerProps) {
	const { onConfirm, ...pickerProps } = props;
	return (
		<FilePickerCore
			{...pickerProps}
			mode='directory'
			multiple={false}
			onConfirm={(result) => onConfirm(result as Parameters<typeof onConfirm>[0])}
		/>
	);
}

export function SaveFilePicker(props: SaveFilePickerProps) {
	const { onConfirm, ...pickerProps } = props;
	return (
		<FilePickerCore
			{...pickerProps}
			mode='save'
			multiple={false}
			onConfirm={(result) => onConfirm(result as Parameters<typeof onConfirm>[0])}
		/>
	);
}

function FilePickerCore({
	accept,
	allowCreateDirectory = true,
	fileSystem,
	messages: messageOverrides,
	mode,
	multiple = false,
	onCancel,
	onConfirm,
	preview = true,
	showHeader = true,
	suggestedName,
	title,
	...fileManagerProps
}: FilePickerCoreProps) {
	const pickerCapabilities = createPickerCapabilities(allowCreateDirectory, preview);
	const [managerStore] = useState(() =>
		createFileManagerStore({
			capabilities: pickerCapabilities,
			fileSystem,
			initialPath: fileManagerProps.initialPath,
			rootPath: fileManagerProps.rootPath,
			viewMode: fileManagerProps.viewMode,
		}),
	);
	const [pickerStore] = useState(() => createFilePickerStore({ suggestedName }));
	const messages = useMemo(() => ({ ...defaultMessages, ...messageOverrides }), [messageOverrides]);
	return (
		<FilePickerProvider store={pickerStore}>
			<FilePickerRuntime
				accept={accept}
				fileManagerStore={managerStore}
				fileSystem={fileSystem}
				messages={messages}
				mode={mode}
				multiple={multiple}
				onCancel={onCancel}
				onConfirm={onConfirm}
				pickerStore={pickerStore}
			/>
			<FilePickerWorkspace
				{...fileManagerProps}
				accept={accept}
				capabilities={pickerCapabilities}
				fileSystem={fileSystem}
				managerStore={managerStore}
				messages={messages}
				mode={mode}
				multiple={multiple}
				showHeader={showHeader}
				title={title}
			/>
		</FilePickerProvider>
	);
}

function FilePickerWorkspace({
	accept,
	capabilities,
	fileSystem,
	managerStore,
	messages,
	mode,
	multiple = false,
	showHeader,
	title,
	...props
}: Omit<FilePickerCoreProps, 'onCancel' | 'onConfirm' | 'suggestedName'> & {
	capabilities: ReturnType<typeof createPickerCapabilities>;
	managerStore: FileManagerStore;
	messages: FilePickerMessages;
}) {
	const actions = useFilePickerActions();
	const acceptIndex = useFilePickerStore((state) => state.filter.acceptIndex);
	const safeAcceptIndex = accept?.length ? Math.min(acceptIndex, accept.length - 1) : 0;
	const activeAccept = accept?.[safeAcceptIndex];
	const acceptedTypes = useMemo(() => (activeAccept ? [activeAccept] : accept), [accept, activeAccept]);
	useEffect(() => {
		if (acceptIndex !== safeAcceptIndex) actions.setAcceptIndex(safeAcceptIndex);
	}, [acceptIndex, actions, safeAcceptIndex]);
	const filterEntry = useMemo(
		() =>
			mode === 'directory'
				? (entry: Parameters<typeof matchesFilePickerAccept>[0]) => entry.kind === 'directory'
				: (entry: Parameters<typeof matchesFilePickerAccept>[0]) => matchesFilePickerAccept(entry, acceptedTypes),
		[acceptedTypes, mode],
	);
	const listingEntries = useStore(managerStore, (state) => state.listing.entries);
	const selectedPaths = useStore(managerStore, (state) => state.selection.paths);
	useEffect(() => {
		const allowed = new Set(listingEntries.filter(filterEntry).map((entry) => entry.path));
		const next = selectedPaths.filter((path) => allowed.has(path));
		if (next.length !== selectedPaths.length) managerStore.getState().actions.selectAll(next);
	}, [filterEntry, listingEntries, managerStore, selectedPaths]);
	const emptyState = (
		<div className='grid min-h-full place-items-center p-6 text-center'>
			<div>
				<FolderOpen className='text-base-content/30 mx-auto size-9' />
				<div className='mt-2 text-sm font-medium'>
					{mode === 'directory' ? messages.emptyDirectory : messages.emptyFiles}
				</div>
			</div>
		</div>
	);
	return (
		<>
			<FileManager
				{...props}
				capabilities={capabilities}
				emptyState={emptyState}
				fileSystem={fileSystem}
				filterEntry={filterEntry}
				footer={
					<FilePickerFooter
						accept={accept}
						acceptIndex={safeAcceptIndex}
						managerStore={managerStore}
						messages={messages}
						mode={mode}
						multiple={multiple}
					/>
				}
				onOpenFile={(entry) => {
					if (mode === 'save') actions.setName(entry.name);
					actions.confirm();
				}}
				onActivateEntry={(entry) => {
					if (entry.kind === 'directory') actions.beginNavigation();
				}}
				selectionMode={mode === 'open' && multiple ? 'multiple' : 'single'}
				showHeader={showHeader}
				store={managerStore}
				title={title ?? getDefaultTitle(mode, multiple)}
			/>
			<FilePickerOverwriteDialog messages={messages} />
		</>
	);
}

function FilePickerFooter({
	accept,
	acceptIndex,
	managerStore,
	messages,
	mode,
	multiple,
}: {
	accept?: FilePickerCoreProps['accept'];
	acceptIndex: number;
	managerStore: FileManagerStore;
	messages: FilePickerMessages;
	mode: FilePickerCoreProps['mode'];
	multiple: boolean;
}) {
	const actions = useFilePickerActions();
	const name = useFilePickerStore((state) => state.input.name);
	const request = useFilePickerStore((state) => state.request);
	const navigationPending = useFilePickerStore((state) => state.navigation.pending);
	const fileManager = useStore(managerStore, (state) => state);
	const selectedEntries = fileManager.listing.entries.filter((entry) =>
		fileManager.selection.paths.includes(entry.path),
	);
	const activeAccept = accept?.[acceptIndex];
	const acceptedTypes = activeAccept ? [activeAccept] : accept;
	const acceptEntries = withFilePickerAcceptKeys(accept ?? []);
	const selectedFiles = selectedEntries.filter(
		(entry) => entry.kind === 'file' && matchesFilePickerAccept(entry, acceptedTypes),
	);
	const selectedDirectory = selectedEntries.find((entry) => entry.kind === 'directory');
	const selectedFilePath = selectedFiles[0]?.path;
	useEffect(() => {
		if (mode === 'save' && selectedFiles[0]) actions.setName(selectedFiles[0].name);
	}, [actions, mode, selectedFilePath]);
	const disabled =
		request.status === 'checking' ||
		navigationPending ||
		fileManager.listing.status === 'loading' ||
		(mode === 'open' && selectedFiles.length === 0 && !selectedDirectory) ||
		(mode === 'save' && !selectedDirectory && !name.trim());
	const selectionSummary =
		mode === 'directory'
			? (selectedDirectory?.path ?? fileManager.navigation.path)
			: selectedFiles.length
				? multiple
					? `已选择 ${selectedFiles.length} 个文件`
					: selectedFiles[0].name
				: '';
	const fileManagerError = fileManager.operation.error ?? fileManager.listing.error;
	const statusMessage = navigationPending
		? (fileManager.listing.requestedPath ?? messages.openingDirectory)
		: request.status === 'checking'
			? messages.savingTarget
			: (request.error ?? fileManagerError ?? fileManager.listing.requestedPath ?? selectionSummary);
	return (
		<footer className='border-base-300 bg-base-100 shrink-0 border-t px-3 py-2'>
			{mode === 'save' ? (
				<label className='mb-2 flex items-center gap-2 text-xs'>
					<span className='shrink-0 font-medium'>{messages.fileName}</span>
					<input
						aria-label={messages.fileName}
						className='input input-sm min-w-0 flex-1'
						value={name}
						onChange={(event) => actions.setName(event.target.value)}
						onKeyDown={(event) => {
							if (event.key === 'Enter' && !disabled) {
								event.preventDefault();
								actions.confirm();
							}
						}}
					/>
				</label>
			) : null}
			<LeftCenterRightLayout
				className={accept?.length ? 'gap-2 max-sm:grid-cols-[minmax(0,1fr)_auto]' : 'gap-2'}
				leftClassName={accept?.length ? 'max-sm:row-start-2' : undefined}
				left={
					<span
						role={request.error || fileManagerError ? 'alert' : request.status === 'checking' ? 'status' : undefined}
						className='text-base-content/55 min-w-0 truncate text-[11px]'
					>
						{statusMessage}
					</span>
				}
				center={
					accept?.length ? (
						<label className='flex items-center gap-1.5 text-[11px]'>
							<span className='text-base-content/55 shrink-0 whitespace-nowrap'>{messages.fileType}</span>
							<select
								aria-label={messages.fileType}
								className='select select-xs max-w-44'
								value={acceptIndex}
								onChange={(event) => actions.setAcceptIndex(event.target.selectedIndex)}
							>
								{acceptEntries.map(({ group, key }, index) => (
									<option key={key} value={index}>
										{group.description ?? `类型 ${index + 1}`}
									</option>
								))}
							</select>
						</label>
					) : null
				}
				centerClassName={
					accept?.length
						? 'max-sm:col-span-2 max-sm:col-start-1 max-sm:row-start-1 max-sm:justify-self-stretch'
						: undefined
				}
				right={
					<div className='flex items-center gap-2'>
						<button type='button' className='btn btn-ghost btn-sm' onClick={actions.cancel}>
							{messages.cancel}
						</button>
						<button type='button' className='btn btn-neutral btn-sm' disabled={disabled} onClick={actions.confirm}>
							{mode === 'directory'
								? messages.confirmDirectory
								: mode === 'save'
									? messages.confirmSave
									: messages.confirmOpen}
						</button>
					</div>
				}
				rightClassName={accept?.length ? 'max-sm:col-start-2 max-sm:row-start-2' : undefined}
			/>
		</footer>
	);
}

function filePickerAcceptKey(group: { accept: Record<string, readonly string[]>; description?: string }) {
	const entries = Object.entries(group.accept)
		.sort(([left], [right]) => left.localeCompare(right))
		.map(([type, extensions]) => `${type}:${[...extensions].sort().join(',')}`)
		.join('|');
	return `${group.description ?? ''}:${entries}`;
}

function withFilePickerAcceptKeys(groups: readonly FilePickerAcceptType[]) {
	const occurrences = new Map<string, number>();
	return groups.map((group) => {
		const identity = filePickerAcceptKey(group);
		const occurrence = occurrences.get(identity) ?? 0;
		occurrences.set(identity, occurrence + 1);
		return { group, key: `${identity}:${occurrence}` };
	});
}

function FilePickerOverwriteDialog({ messages }: { messages: FilePickerMessages }) {
	const ref = useRef<HTMLDialogElement>(null);
	const titleId = useId();
	const target = useFilePickerStore((state) => state.overwrite.target);
	const actions = useFilePickerActions();
	useEffect(() => {
		const dialog = ref.current;
		if (!dialog) return;
		if (target && !dialog.open) dialog.showModal();
		if (!target && dialog.open) dialog.close();
	}, [target]);
	if (!target) return null;
	return (
		<dialog
			ref={ref}
			aria-labelledby={titleId}
			className='bg-base-100 text-base-content m-auto w-[min(28rem,calc(100vw-2rem))] rounded-md p-0 shadow-2xl backdrop:bg-black/35'
			onCancel={(event) => {
				event.preventDefault();
				actions.clearOverwrite();
			}}
		>
			<form
				className='flex flex-col'
				onSubmit={(event: FormEvent) => {
					event.preventDefault();
					actions.confirmOverwrite();
				}}
			>
				<header className='border-base-300 flex items-center gap-2 border-b px-4 py-3'>
					<Save aria-hidden='true' className='size-4' />
					<h3 id={titleId} className='min-w-0 flex-1 text-sm font-semibold'>
						{messages.overwriteTitle}
					</h3>
					<button
						type='button'
						aria-label='关闭'
						className='btn btn-ghost btn-square btn-xs'
						onClick={actions.clearOverwrite}
					>
						<X aria-hidden='true' className='size-4' />
					</button>
				</header>
				<div className='p-4 text-sm leading-6'>{messages.overwriteDescription(target.name)}</div>
				<footer className='border-base-300 flex justify-end gap-2 border-t px-4 py-3'>
					<button type='button' className='btn btn-ghost btn-sm' onClick={actions.clearOverwrite}>
						{messages.cancel}
					</button>
					<button type='submit' className='btn btn-error btn-sm'>
						{messages.overwrite}
					</button>
				</footer>
			</form>
		</dialog>
	);
}

function getDefaultTitle(mode: FilePickerCoreProps['mode'], multiple: boolean): ReactNode {
	if (mode === 'directory') return '选择文件夹';
	if (mode === 'save') return '保存文件';
	return multiple ? '打开文件' : '打开文件';
}

function createPickerCapabilities(createDirectory: boolean, preview: boolean) {
	return {
		copy: false,
		createDirectory,
		createFile: false,
		delete: false,
		download: false,
		edit: false,
		move: false,
		preview,
		rename: false,
		upload: false,
	};
}

'use client';

import type { ReactNode } from 'react';
import { cn } from '@/lib/utils';
import type { FileManagerFileStat } from '../file-manager';
import type { WindowManagerCapabilities, WindowManagerOpenOptions, WindowManagerStore } from '../window-manager';
import { DirectoryPicker, FilePicker, SaveFilePicker } from './file-picker';
import type {
	DirectoryPickerProps,
	DirectoryPickerResult,
	FilePickerMode,
	FilePickerProps,
	SaveFilePickerProps,
	SaveFilePickerResult,
} from './file-picker-types';

export const FILE_PICKER_WINDOW_KIND = 'file-picker';

type PickerWindowOptions = Omit<
	WindowManagerOpenOptions,
	'capabilities' | 'data' | 'duplicate' | 'id' | 'key' | 'kind' | 'persistence' | 'title'
> & { capabilities?: Omit<Partial<WindowManagerCapabilities>, 'close'>; title?: string };

type ShowFilePickerBaseOptions = Omit<FilePickerProps, 'onCancel' | 'onConfirm'> & {
	window?: PickerWindowOptions;
	windowManager: WindowManagerStore;
};

export type ShowFilePickerOptions = ShowFilePickerBaseOptions & { multiple?: false };
export type ShowMultipleFilePickerOptions = ShowFilePickerBaseOptions & { multiple: true };
export type ShowDirectoryPickerOptions = Omit<DirectoryPickerProps, 'onCancel' | 'onConfirm'> & {
	window?: PickerWindowOptions;
	windowManager: WindowManagerStore;
};
export type ShowSaveFilePickerOptions = Omit<SaveFilePickerProps, 'onCancel' | 'onConfirm'> & {
	window?: PickerWindowOptions;
	windowManager: WindowManagerStore;
};

export type FilePickerWindowData =
	| { mode: 'directory'; picker: DirectoryPickerProps; type: typeof FILE_PICKER_WINDOW_KIND }
	| { mode: 'open'; picker: FilePickerProps; type: typeof FILE_PICKER_WINDOW_KIND }
	| { mode: 'save'; picker: SaveFilePickerProps; type: typeof FILE_PICKER_WINDOW_KIND };

export type FilePickerWindowDescriptor = { data?: unknown; kind: string };

let pickerWindowSequence = 0;

export function showFilePicker(options: ShowMultipleFilePickerOptions): Promise<FileManagerFileStat[] | undefined>;
export function showFilePicker(options: ShowFilePickerOptions): Promise<FileManagerFileStat | undefined>;
export function showFilePicker(
	options: ShowFilePickerOptions | ShowMultipleFilePickerOptions,
): Promise<FileManagerFileStat | FileManagerFileStat[] | undefined> {
	const { windowManager, window, ...picker } = options;
	const common = { mode: 'open' as const, picker, title: window?.title ?? '打开文件', window, windowManager };
	return options.multiple
		? showPickerWindow<FileManagerFileStat[]>({ ...common, validateResult: isFileStatArray })
		: showPickerWindow<FileManagerFileStat>({ ...common, validateResult: isFileStat });
}

export function showDirectoryPicker(options: ShowDirectoryPickerOptions): Promise<DirectoryPickerResult | undefined> {
	const { windowManager, window, ...picker } = options;
	return showPickerWindow({
		mode: 'directory',
		picker,
		title: window?.title ?? '选择文件夹',
		window,
		windowManager,
		validateResult: isDirectoryResult,
	});
}

export function showSaveFilePicker(options: ShowSaveFilePickerOptions): Promise<SaveFilePickerResult | undefined> {
	const { windowManager, window, ...picker } = options;
	return showPickerWindow({
		mode: 'save',
		picker,
		title: window?.title ?? '保存文件',
		window,
		windowManager,
		validateResult: isSaveResult,
	});
}

export function renderFilePickerWindow(window: FilePickerWindowDescriptor): ReactNode {
	return window.kind === FILE_PICKER_WINDOW_KIND && isFilePickerWindowData(window.data) ? (
		<FilePickerWindow data={window.data} />
	) : null;
}

export function FilePickerWindow({ data }: { data: FilePickerWindowData }) {
	const props = {
		...data.picker,
		className: cn('size-full min-h-0 rounded-none border-0', data.picker.className),
		showHeader: data.picker.showHeader ?? false,
	};
	if (data.mode === 'directory') return <DirectoryPicker {...(props as DirectoryPickerProps)} />;
	if (data.mode === 'save') return <SaveFilePicker {...(props as SaveFilePickerProps)} />;
	return <FilePicker {...(props as FilePickerProps)} />;
}

function showPickerWindow<Result>({
	mode,
	picker,
	title,
	validateResult,
	window,
	windowManager,
}: {
	mode: FilePickerMode;
	picker: Omit<DirectoryPickerProps | FilePickerProps | SaveFilePickerProps, 'onCancel' | 'onConfirm'>;
	title: string;
	validateResult: (value: unknown) => value is Result;
	window?: PickerWindowOptions;
	windowManager: WindowManagerStore;
}): Promise<Result | undefined> {
	const id = createPickerWindowId();
	return new Promise<Result | undefined>((resolve, reject) => {
		let activeId = id;
		let opened = false;
		let settled = false;
		let unsubscribeEvents: () => void = () => {};
		let unsubscribeState: () => void = () => {};
		const settle = (result: Result | undefined) => {
			if (settled) return;
			settled = true;
			unsubscribeEvents();
			unsubscribeState();
			resolve(result);
		};
		unsubscribeEvents = windowManager.subscribeEvents((event) => {
			if (event.type !== 'closed' || event.id !== activeId) return;
			settle(validateResult(event.result) ? event.result : undefined);
		});
		unsubscribeState = windowManager.subscribe((state) => {
			const exists = Boolean(state.windows[activeId]);
			if (exists) opened = true;
			if (!opened || exists || settled) return;
			queueMicrotask(() => {
				if (!settled && !windowManager.getState().windows[activeId]) settle(undefined);
			});
		});
		const actions = windowManager.getState().actions;
		const close = (result?: Result) => actions.close(activeId, result);
		const data = {
			mode,
			picker: {
				...picker,
				onCancel: () => {
					close();
				},
				onConfirm: (result: Result) => {
					close(result);
				},
			},
			type: FILE_PICKER_WINDOW_KIND,
		} as unknown as FilePickerWindowData;
		try {
			activeId = actions.open({
				icon: mode === 'save' ? 'save' : 'folder-open',
				showInDock: true,
				...window,
				bounds: { width: 920, height: 640, ...window?.bounds },
				capabilities: { ...window?.capabilities, close: true },
				data,
				duplicate: 'allow',
				id,
				key: id,
				kind: FILE_PICKER_WINDOW_KIND,
				persistence: 'none',
				size: { minWidth: 560, minHeight: 440, ...window?.size },
				title,
			});
			opened = Boolean(windowManager.getState().windows[activeId]);
		} catch (error) {
			if (!settled) {
				settled = true;
				unsubscribeEvents();
				unsubscribeState();
				reject(error);
			}
		}
	});
}

function createPickerWindowId(): string {
	pickerWindowSequence += 1;
	return `file-picker-${Date.now().toString(36)}-${pickerWindowSequence.toString(36)}`;
}

function isFilePickerWindowData(value: unknown): value is FilePickerWindowData {
	if (!isRecord(value) || value.type !== FILE_PICKER_WINDOW_KIND) return false;
	if (value.mode !== 'open' && value.mode !== 'directory' && value.mode !== 'save') return false;
	if (!isRecord(value.picker) || !isFileSystem(value.picker.fileSystem)) return false;
	if (value.picker.accept !== undefined && !isAccept(value.picker.accept)) return false;
	if (value.picker.messages !== undefined && !isMessages(value.picker.messages)) return false;
	if (value.picker.multiple !== undefined && typeof value.picker.multiple !== 'boolean') return false;
	if (value.picker.suggestedName !== undefined && typeof value.picker.suggestedName !== 'string') return false;
	return typeof value.picker.onCancel === 'function' && typeof value.picker.onConfirm === 'function';
}

function isFileSystem(value: unknown): boolean {
	if (!isRecord(value)) return false;
	return ['copy', 'exists', 'mkdir', 'readFile', 'readdir', 'rename', 'rm', 'stat', 'writeFile'].every(
		(method) => typeof value[method] === 'function',
	);
}

function isFileStat(value: unknown): value is FileManagerFileStat {
	return (
		isRecord(value) &&
		value.kind === 'file' &&
		typeof value.path === 'string' &&
		typeof value.name === 'string' &&
		typeof value.directory === 'string' &&
		isRecord(value.meta) &&
		typeof value.mtime === 'number' &&
		Number.isFinite(value.mtime) &&
		typeof value.size === 'number' &&
		Number.isFinite(value.size)
	);
}

function isFileStatArray(value: unknown): value is FileManagerFileStat[] {
	return Array.isArray(value) && value.length > 0 && value.every(isFileStat);
}

function isDirectoryResult(value: unknown): value is DirectoryPickerResult {
	return isRecord(value) && value.kind === 'directory' && typeof value.path === 'string';
}

function isSaveResult(value: unknown): value is SaveFilePickerResult {
	return (
		isRecord(value) &&
		value.kind === 'file' &&
		typeof value.path === 'string' &&
		typeof value.name === 'string' &&
		typeof value.directory === 'string' &&
		(value.existing === undefined || isFileStat(value.existing))
	);
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === 'object' && value !== null;
}

function isAccept(value: unknown): boolean {
	return (
		Array.isArray(value) &&
		value.every(
			(group) =>
				isRecord(group) &&
				(group.description === undefined || typeof group.description === 'string') &&
				isRecord(group.accept) &&
				Object.entries(group.accept).every(
					([mime, extensions]) =>
						mime.length > 0 && Array.isArray(extensions) && extensions.every((item) => typeof item === 'string'),
				),
		)
	);
}

function isMessages(value: unknown): boolean {
	if (!isRecord(value)) return false;
	return Object.entries(value).every(([key, item]) =>
		key === 'overwriteDescription' ? typeof item === 'function' : typeof item === 'string',
	);
}

